enum ReportCategory { spam, impersonation, harassment, threat, childSafety, other }
enum TriagePriority { routine, elevated, urgentHumanReview }
class SafetyReport { const SafetyReport({required this.id,required this.category,this.independentReports=1,this.hasEvidenceReference=false}); final String id; final ReportCategory category; final int independentReports; final bool hasEvidenceReference; }
class ReportTriageResult { const ReportTriageResult(this.priority,this.reasons); final TriagePriority priority; final List<String> reasons; }
class CommunityReportTriage { const CommunityReportTriage(); ReportTriageResult assess(SafetyReport r){if(r.category==ReportCategory.threat||r.category==ReportCategory.childSafety)return const ReportTriageResult(TriagePriority.urgentHumanReview,['High severity needs trained human review']);final reasons=<String>[];if(r.hasEvidenceReference)reasons.add('Evidence needs independent verification');if(r.independentReports>=5)reasons.add('Multiple reports need review, not an automatic verdict');final high=r.independentReports>=5||r.hasEvidenceReference||r.category==ReportCategory.harassment||r.category==ReportCategory.impersonation;return ReportTriageResult(high?TriagePriority.elevated:TriagePriority.routine,List.unmodifiable(reasons));}}
